/**
 * Generates every platform's icon files from the single source, packages/core/src/icons/*.ts.
 *
 *   npx tsx scripts/gen.ts            write everything
 *   npx tsx scripts/gen.ts --check    fail when a committed generated file (Kotlin, Swift) is out of date
 *
 * Web packages (core all.ts, react / vue / svelte icons + index + all) are build outputs and git-ignored;
 * the Kotlin and Swift files are committed, because Gradle includeBuild and SwiftPM read the sources directly.
 * Anything the native generators do not recognise fails the run instead of being skipped.
 */
import type { IconData } from "../packages/core/src/index.js";

import { mkdirSync, readdirSync, readFileSync, rmSync, writeFileSync } from "node:fs";
import path from "node:path";
import { fileURLToPath, pathToFileURL } from "node:url";

import { ALIASES } from "../packages/core/src/aliases.js";
import { genKotlin } from "./gen-kotlin.js";
import { genSwift } from "./gen-swift.js";

export const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "..");
const CORE_ICONS = path.join(ROOT, "packages/core/src/icons");
export const HEADER = "// Code generated by scripts/gen.ts from packages/core/src/icons. DO NOT EDIT.";

/** Every icon, in key order. */
export async function loadIcons(): Promise<IconData[]> {
  const files = readdirSync(CORE_ICONS)
    .filter((f) => f.endsWith(".ts"))
    .sort();
  const icons: IconData[] = [];
  for (const file of files) {
    const mod = (await import(pathToFileURL(path.join(CORE_ICONS, file)).href)) as Record<string, IconData>;
    const [data, ...extra] = Object.values(mod);
    if (!data || extra.length) throw new Error(`${file}: expected exactly one icon export`);
    if (`${data.key}.ts` !== file) throw new Error(`${file}: key ${data.key} does not match the file name`);
    if (mod[data.name] !== data) throw new Error(`${file}: export name must be ${data.name}`);
    icons.push(data);
  }
  return icons.sort((a, b) => (a.key < b.key ? -1 : a.key > b.key ? 1 : 0));
}

/** Every exported name of an icon: its name, its aliases, each also with an `Icon` suffix. */
export function exportNames(icon: IconData): string[] {
  return [icon.name, ...(ALIASES[icon.key] ?? [])].flatMap((n) => [n, `${n}Icon`]);
}

/**
 * Makes `dir` hold exactly `files` (paths relative to it): writes the changed ones and removes the rest, leaving
 * unchanged files untouched so Gradle and SwiftPM don't rebuild them. With `check`, only compares. Returns the stale paths.
 */
export function writeTree(dir: string, files: Map<string, string>, check: boolean): string[] {
  const abs = path.join(ROOT, dir);
  const stale: string[] = [];
  const extra = new Set(listFiles(abs));
  for (const [rel, text] of files) {
    extra.delete(rel);
    let current: string | undefined;
    try {
      current = readFileSync(path.join(abs, rel), "utf8");
    } catch {
      current = undefined;
    }
    if (current === text) continue;
    stale.push(path.join(dir, rel));
    if (!check) {
      mkdirSync(path.dirname(path.join(abs, rel)), { recursive: true });
      writeFileSync(path.join(abs, rel), text);
    }
  }
  for (const rel of extra) {
    stale.push(path.join(dir, rel));
    if (!check) rmSync(path.join(abs, rel));
  }
  return check ? stale : [];
}

function listFiles(dir: string, prefix = ""): string[] {
  let entries;
  try {
    entries = readdirSync(dir, { withFileTypes: true });
  } catch {
    return [];
  }
  return entries.flatMap((e) => (e.isDirectory() ? listFiles(path.join(dir, e.name), `${prefix}${e.name}/`) : [`${prefix}${e.name}`]));
}

const quoteKey = (key: string) => (/^[a-z_$][\w$]*$/.test(key) ? key : JSON.stringify(key));

function webIndexLines(icons: IconData[], from: (key: string) => string, local = (i: IconData) => i.name): string[] {
  return icons.map((i) => {
    const names = exportNames(i).map((n) => (n === local(i) ? n : `${local(i)} as ${n}`));
    return `export { ${names.join(", ")} } from "${from(i.key)}";`;
  });
}

function webAll(icons: IconData[], type: string, typeImport: string, from: (key: string) => string, importOf = (i: IconData) => `import { ${i.name} } from "${from(i.key)}";`): string {
  return [
    HEADER,
    typeImport,
    "",
    ...icons.map(importOf),
    "",
    "/** Every icon by kebab-case name. */",
    `export const ICONS: Record<string, ${type}> = {`,
    ...icons.map((i) => `  ${quoteKey(i.key)}: ${i.name},`),
    "};",
    "",
    "export type IconName = keyof typeof ICONS;",
    "",
    "export const ICON_NAMES = Object.keys(ICONS);",
    "",
  ].join("\n");
}

/** `names`: every icon key and no components, for pickers and lookup tables that load icons on demand. */
function namesModule(icons: IconData[]): string {
  return [
    HEADER,
    "/** Every icon key (kebab-case, also the file name under `icons/`), without loading any icon. */",
    "export const ICON_NAMES = [",
    ...icons.map((i) => `  ${JSON.stringify(i.key)},`),
    "] as const;",
    "",
    "/** One icon key. */",
    "export type IconName = (typeof ICON_NAMES)[number];",
    "",
  ].join("\n");
}

function genCore(icons: IconData[]): void {
  writeFileSync(path.join(ROOT, "packages/core/src/names.ts"), namesModule(icons));
  writeFileSync(
    path.join(ROOT, "packages/core/src/all.ts"),
    webAll(icons, "IconData", 'import type { IconData } from "./types.js";', (k) => `./icons/${k}.js`),
  );
}

/** One wrapper per icon (`Bell = createIcon("Bell", "bell", data)`), plus the package index and `all`. */
function genWeb(pkg: string, icons: IconData[], opts: { create: string; createFrom: string; type: string; typeFrom: string; head: string[] }): void {
  const files = new Map<string, string>();
  for (const i of icons) {
    files.set(
      `${i.key}.ts`,
      [
        HEADER,
        `import { ${i.name} as data } from "pulsoicon-core/icons/${i.key}";`,
        "",
        `import { ${opts.create} } from "${opts.createFrom}";`,
        "",
        `export const ${i.name} = ${opts.create}("${i.name}", "${i.key}", data);`,
        "",
      ].join("\n"),
    );
  }
  writeTree(`packages/${pkg}/src/icons`, files, false);
  writeFileSync(path.join(ROOT, `packages/${pkg}/src/names.ts`), namesModule(icons));
  writeFileSync(path.join(ROOT, `packages/${pkg}/src/index.ts`), [HEADER, ...opts.head, "", ...webIndexLines(icons, (k) => `./icons/${k}.js`), ""].join("\n"));
  writeFileSync(
    path.join(ROOT, `packages/${pkg}/src/all.ts`),
    webAll(icons, opts.type, `import type { ${opts.type} } from "${opts.typeFrom}";`, (k) => `./icons/${k}.js`),
  );
}

/** Svelte: one component file per icon wrapping Icon.svelte (Svelte compiles components, it cannot build them from a function). */
function genSvelte(icons: IconData[]): void {
  const files = new Map<string, string>();
  for (const i of icons) {
    files.set(
      `${i.key}.svelte`,
      [
        `<!-- ${HEADER.slice(3)} -->`,
        '<script lang="ts">',
        '  import type { IconProps } from "../types.js";',
        "",
        `  import { ${i.name} as data } from "pulsoicon-core/icons/${i.key}";`,
        "",
        '  import Icon from "../Icon.svelte";',
        "",
        "  let { ...props }: IconProps = $props();",
        "  let icon: Icon;",
        "",
        "  /** Plays the icon's motion; resolves when it has finished. */",
        "  export const startAnimation = (): Promise<void> => icon.startAnimation();",
        "  /** Returns to the resting frame; resolves when it is there. */",
        "  export const stopAnimation = (): Promise<void> => icon.stopAnimation();",
        "</script>",
        "",
        "<Icon bind:this={icon} {...props} {data} />",
        "",
      ].join("\n"),
    );
  }
  writeTree("packages/svelte/src/icons", files, false);
  writeFileSync(path.join(ROOT, "packages/svelte/src/names.ts"), namesModule(icons));
  const head = [
    'export { default as Icon } from "./Icon.svelte";',
    'export type { IconHandle, IconProps, PulsoIcon } from "./types.js";',
    'export { RECIPE_NAMES, RECIPES } from "pulsoicon-core";',
    'export type { Recipe, RecipeName, RecipeParams, RecipeVariants } from "pulsoicon-core";',
  ];
  const from = (k: string) => `./icons/${k}.svelte`;
  writeFileSync(path.join(ROOT, "packages/svelte/src/index.ts"), [HEADER, ...head, "", ...webIndexLines(icons, from, () => "default"), ""].join("\n"));
  writeFileSync(
    path.join(ROOT, "packages/svelte/src/all.ts"),
    webAll(icons, "PulsoIcon", 'import type { PulsoIcon } from "./types.js";', from, (i) => `import ${i.name} from "${from(i.key)}";`),
  );
}

async function main(): Promise<void> {
  const check = process.argv.includes("--check");
  const icons = await loadIcons();
  const known = new Set(icons.map((i) => i.key));
  for (const key of Object.keys(ALIASES)) if (!known.has(key)) throw new Error(`aliases.ts: unknown icon ${key}`);
  const taken = new Map<string, string>();
  for (const i of icons) {
    for (const n of exportNames(i)) {
      const other = taken.get(n);
      if (other) throw new Error(`${n} is exported by both ${other} and ${i.key}`);
      taken.set(n, i.key);
    }
  }

  const stale = [...genKotlin(icons, check), ...genSwift(icons, check)];
  if (check) {
    if (stale.length) {
      console.error(`Generated files are out of date (run npx tsx scripts/gen.ts):\n  ${stale.slice(0, 20).join("\n  ")}${stale.length > 20 ? `\n  … ${stale.length - 20} more` : ""}`);
      process.exit(1);
    }
    console.log(`gen --check: ${icons.length} icons up to date`);
    return;
  }

  genCore(icons);
  genWeb("react", icons, {
    create: "createIcon",
    createFrom: "../runtime/createIcon.js",
    type: "PulsoIcon",
    typeFrom: "./runtime/createIcon.js",
    head: [
      'export { createIcon } from "./runtime/createIcon.js";',
      'export type { AnimationProps, BaseIconProps, DistributiveOmit, IconHandle, IconMotion, IconNode, IconProps, IconSpec, PulsoIcon, SolidNode, SolidRole } from "./runtime/createIcon.js";',
      'export { RECIPE_NAMES, RECIPES } from "pulsoicon-core";',
      'export type { Recipe, RecipeName, RecipeParams, RecipeVariants } from "pulsoicon-core";',
    ],
  });
  genWeb("vue", icons, {
    create: "createIcon",
    createFrom: "../createIcon.js",
    type: "PulsoIcon",
    typeFrom: "./createIcon.js",
    head: [
      'export { createIcon } from "./createIcon.js";',
      'export type { IconHandle, IconProps, PulsoIcon } from "./createIcon.js";',
      'export { RECIPE_NAMES, RECIPES } from "pulsoicon-core";',
      'export type { Recipe, RecipeName, RecipeParams, RecipeVariants } from "pulsoicon-core";',
    ],
  });
  genSvelte(icons);
  console.log(`gen: ${icons.length} icons, ${Object.values(ALIASES).flat().length} other names`);
}

await main();
